String tr(String lang, String key, {Map<String, String> vars = const {}}) {
  var s = _s[key]?[lang] ?? _s[key]?['en'] ?? key;
  vars.forEach((k, v) => s = s.replaceAll('{$k}', v));
  return s;
}

String trError(String lang, String code) => _e[code]?[lang] ?? _e[code]?['en'] ?? code;
